use vstd::prelude::*;

verus! {
    spec fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool
        requires
            start + sub.len() <= main.len(),
    {
        if start + sub.len() > main.len() {
            false
        } else {
            let mut j: usize = 0;
            while j < sub.len()
                invariant
                    j <= sub.len(),
                    main.len() >= start + j,
                    sub.len() <= main.len() - start,
                decreases sub.len() - j,
            {
                if main[start + j] != sub[j] {
                    return false;
                }
                j = j + 1;
            }
            true
        }
    }

    fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool
        requires
            sub.len() <= main.len(),
    {
        if sub.is_empty() {
            return true;
        }
        
        if sub.len() > main.len() {
            return false;
        }
        
        let mut i: usize = 0;
        while i <= main.len() - sub.len()
            invariant
                i <= main.len() - sub.len(),
                sub.len() <= main.len(),
            decreases main.len() - sub.len() - i,
        {
            if check_match_at(main, sub, i) {
                return true;
            }
            i = i + 1;
        }
        
        false
    }
}

